package com.github.tartaricacid.touhoulittlemaid.client.chat;
import com.github.tartaricacid.touhoulittlemaid.TouhouLittleMaid;import net.minecraft.client.resources.IResourceManager;import net.minecraft.client.resources.IResourceManagerReloadListener;import net.minecraft.util.ResourceLocation;import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.ArrayList;import java.util.List;
public final class LegacyKaomojiLoader implements IResourceManagerReloadListener{public static final LegacyKaomojiLoader INSTANCE=new LegacyKaomojiLoader();private final List<String> values=new ArrayList<String>();private LegacyKaomojiLoader(){}public String forEntity(int id){return values.isEmpty()?"":values.get((id&Integer.MAX_VALUE)%values.size());}public void onResourceManagerReload(IResourceManager manager){values.clear();try{BufferedReader r=new BufferedReader(new InputStreamReader(manager.getResource(new ResourceLocation(TouhouLittleMaid.MOD_ID,"data/kaomoji.txt")).getInputStream(),"UTF-8"));String line;while((line=r.readLine())!=null)if(!line.trim().isEmpty()&&!line.startsWith("#"))values.add(line.trim());r.close();}catch(Exception ignored){}}}
